for _, v in pairs(DUMP) do
  if v.m then local h={} for i=1,#v.m do h[v.m[i]]=true end v.m=h end
  if v.e then local h={} for i=1,#v.e do h[v.e[i]]=true end v.e=h end
  if v.p then local h={} for i=1,#v.p do h[v.p[i]]=true end v.p=h end
end
for k, v in pairs(ENUMS) do
  local h={} for i=1,#v do h[v[i]]=true end ENUMS[k]={__items=v,__hash=h}
end
local ENUM_REVERSE = {}
for enumName, vals in pairs(ENUM_VALUES) do
  local r = {}
  for itemName, val in pairs(vals) do r[val] = itemName end
  ENUM_REVERSE[enumName] = r
end
local ENUM_VALUE_INDEX = {}
for enumName, r in pairs(ENUM_REVERSE) do
  for val, itemName in pairs(r) do
    local list = ENUM_VALUE_INDEX[val]
    if not list then
      list = {}
      ENUM_VALUE_INDEX[val] = list
    end
    table.insert(list, { enum = enumName, item = itemName })
  end
end
