local Api = {}
local CORE_CAT = {
  global='global',Globals='global',LuauCore='global',LuauGlobal='global',
  keyword='keyword',Keyword='keyword',Keywords='keyword',
  metamethod='metamethod',Metamethod='metamethod',Metamethods='metamethod',
}
local MAX_CHAIN = 200
local function chainFind(className, key, token)
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local d = DUMP[cur]
    if d and d[key] and d[key][token] then return cur end
    cur = SUPER[cur]; s = s + 1
  end
  return nil
end

local function chainLookup(className, tblName, token)
  local cur = className
  local s = 0
  local tbl = _G[tblName] or (tblName == "PARAMS" and PARAMS)
                  or (tblName == "RETURNS" and RETURNS)
                  or (tblName == "EVENT_PARAMS" and EVENT_PARAMS)
                  or (tblName == "PROP_TYPES" and PROP_TYPES)
                  or (tblName == "SECURITY" and SECURITY)
                  or (tblName == "YIELDS" and YIELDS)
                  or (tblName == "DEPRECATED" and DEPRECATED)
                  or (tblName == "READONLY" and READONLY)
  while cur and s < MAX_CHAIN do
    if tbl[cur] and tbl[cur][token] then return tbl[cur][token], cur end
    cur = SUPER[cur]; s = s + 1
  end
  return nil, nil
end

function Api.Get(token, className)
  if type(token) ~= 'string' or type(className) ~= 'string' then return nil end
  local cat = CORE_CAT[className]
  if cat then
    if cat == 'global' and CORE.globals[token] then return token..'()' end
    if cat == 'keyword' and CORE.keywords[token] then return token end
    if cat == 'metamethod' and CORE.metamethods[token] then return token end
    return nil
  end
  local lib = CORE.libraries[className]
  if lib then
    if lib[token] then return className..'.'..token..'()' end
    return nil
  end
  local dc = chainFind(className, 'm', token)
  if dc then return string.lower(dc)..':'..token..'()' end
  return nil
end

function Api.GetParams(token, className)
  if type(token) ~= 'string' or type(className) ~= 'string' then return nil end
  return (chainLookup(className, "PARAMS", token))
end

function Api.GetReturn(token, className)
  if type(token) ~= 'string' or type(className) ~= 'string' then return nil end
  return (chainLookup(className, "RETURNS", token))
end

function Api.GetSignature(token, className)
  local s = Api.Get(token, className)
  if not s then return nil end
  local p = Api.GetParams(token, className) or ''
  return (s:gsub('%(%)$', '('..p..')'))
end

function Api.GetFullSignature(token, className)
  local sig = Api.GetSignature(token, className)
  if not sig then return nil end
  local ret = Api.GetReturn(token, className)
  if ret then return sig..' -> '..ret end
  return sig
end

function Api.HasEvent(className, eventName)
  return chainFind(className, 'e', eventName) ~= nil
end

function Api.GetEventParams(eventName, className)
  if type(eventName) ~= 'string' or type(className) ~= 'string' then return nil end
  return (chainLookup(className, "EVENT_PARAMS", eventName))
end

function Api.GetEventSignature(eventName, className)
  if not Api.HasEvent(className, eventName) then return nil end
  return eventName..'('..(Api.GetEventParams(eventName, className) or '')..')'
end

function Api.HasProperty(className, propName)
  return chainFind(className, 'p', propName) ~= nil
end

function Api.GetPropertyType(className, propName)
  if type(propName) ~= 'string' or type(className) ~= 'string' then return nil end
  return (chainLookup(className, "PROP_TYPES", propName))
end

function Api.IsPropertyReadOnly(className, propName)
  return chainLookup(className, "READONLY", propName) == true
end

function Api.IsDeprecated(className, memberName)
  return chainLookup(className, "DEPRECATED", memberName) == true
end

function Api.IsYielding(token, className)
  if type(token) ~= 'string' or type(className) ~= 'string' then return false end
  return chainLookup(className, "YIELDS", token) == true
end

function Api.GetSecurity(className, memberName)
  if type(memberName) ~= 'string' or type(className) ~= 'string' then return nil end
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local sec = SECURITY[cur]
    if sec then
      if sec.m and sec.m[memberName] then return sec.m[memberName] end
      if sec.p and sec.p[memberName] then return sec.p[memberName] end
    end
    cur = SUPER[cur]; s = s + 1
  end
  return nil
end

function Api.GetClassChain(className)
  local chain = {}
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    table.insert(chain, cur)
    local sup = SUPER[cur]
    if not sup then break end
    cur = sup; s = s + 1
  end
  return chain
end

function Api.IsA(className, parentClass)
  if className == parentClass then return true end
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local sup = SUPER[cur]
    if sup == parentClass then return true end
    cur = sup; s = s + 1
  end
  return false
end

function Api.WalkChain(className, callback)
  if type(callback) ~= "function" then return end
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    callback(cur, s)
    cur = SUPER[cur]; s = s + 1
  end
end

local function collectChain(className, key)
  local result, seen = {}, {}
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local d = DUMP[cur]
    if d and d[key] then
      for k in pairs(d[key]) do
        if not seen[k] then seen[k] = true; table.insert(result, k) end
      end
    end
    cur = SUPER[cur]; s = s + 1
  end
  table.sort(result)
  return result
end

function Api.GetProperties(c) return collectChain(c, 'p') end
function Api.GetEvents(c)     return collectChain(c, 'e') end
function Api.GetMethods(c)    return collectChain(c, 'm') end

function Api.GetOwnMethods(className)
  local d = DUMP[className]
  if not d or not d.m then return {} end
  local list = {}
  for m in pairs(d.m) do table.insert(list, m) end
  table.sort(list)
  return list
end

function Api.GetOwnEvents(className)
  local d = DUMP[className]
  if not d or not d.e then return {} end
  local list = {}
  for e in pairs(d.e) do table.insert(list, e) end
  table.sort(list)
  return list
end

function Api.GetOwnProperties(className)
  local d = DUMP[className]
  if not d or not d.p then return {} end
  local list = {}
  for p in pairs(d.p) do table.insert(list, p) end
  table.sort(list)
  return list
end

function Api.GetClassTags(className)
  return CLASS_TAGS[className]
end

function Api.ClassesWithTag(tag)
  local result = {}
  for cName, tags in pairs(CLASS_TAGS) do
    if tags[tag] then table.insert(result, cName) end
  end
  table.sort(result)
  return result
end

function Api.GetYieldingMethods(className)
  local result = {}
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local ys = YIELDS[cur]
    if ys then
      for m in pairs(ys) do
        table.insert(result, { name = m, class = cur })
      end
    end
    cur = SUPER[cur]; s = s + 1
  end
  return result
end

function Api.GetDeprecatedMembers(className)
  local result = {}
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local d = DEPRECATED[cur]
    if d then
      for m in pairs(d) do
        table.insert(result, { name = m, class = cur })
      end
    end
    cur = SUPER[cur]; s = s + 1
  end
  return result
end

function Api.FindOverloads(token, className)
  local seen, out = {}, {}
  local cur = className
  local s = 0
  while cur and s < MAX_CHAIN do
    local d = DUMP[cur]
    if d and d.m and d.m[token] then
      local sig = cur..':'..token..'('..(PARAMS[cur] and PARAMS[cur][token] or '')..')'
      local ret = RETURNS[cur] and RETURNS[cur][token]
      if ret then sig = sig..' -> '..ret end
      if not seen[sig] then seen[sig] = true; table.insert(out, sig) end
    end
    cur = SUPER[cur]; s = s + 1
  end
  return out
end

function Api.HasEnum(n) return ENUMS[n] ~= nil end
function Api.HasEnumItem(n, i)
  local e = ENUMS[n]
  return e ~= nil and e.__hash[i] == true
end
function Api.GetEnumItems(n)
  local e = ENUMS[n]
  if not e then return nil end
  local c = {}
  for i = 1, #e.__items do c[i] = e.__items[i] end
  return c
end
function Api.GetEnumNames()
  local ns = {}
  for k in pairs(ENUMS) do table.insert(ns, k) end
  table.sort(ns)
  return ns
end
function Api.GetEnumValue(enumName, itemName)
  local e = ENUM_VALUES[enumName]
  if not e then return nil end
  return e[itemName]
end
function Api.ResolveEnumValue(enumName, numericValue)
  local r = ENUM_REVERSE[enumName]
  if not r then return nil end
  return r[numericValue]
end
function Api.ResolveEnumFull(enumName, numericValue)
  local r = ENUM_REVERSE[enumName]
  if not r then return nil end
  local item = r[numericValue]
  if not item then return nil end
  return "Enum."..enumName.."."..item
end
function Api.FindEnumsByValue(numericValue)
  local list = ENUM_VALUE_INDEX[numericValue]
  if not list then return {} end
  local out = {}
  for i = 1, #list do
    out[i] = { enum = list[i].enum, item = list[i].item }
  end
  return out
end
function Api.FindEnumsByValueFull(numericValue)
  local list = ENUM_VALUE_INDEX[numericValue]
  if not list then return {} end
  local out = {}
  for i = 1, #list do
    out[i] = "Enum."..list[i].enum.."."..list[i].item
  end
  return out
end

function Api.HasDatatype(n)
  return DATATYPES[n] ~= nil
end
function Api.GetDatatype(n)
  local d = DATATYPES[n]
  if not d then return nil end
  return { methods = d.m or {}, properties = d.p or {} }
end
function Api.GetDatatypeNames()
  local ns = {}
  for k in pairs(DATATYPES) do table.insert(ns, k) end
  table.sort(ns)
  return ns
end
function Api.HasDatatypeMethod(dt, method)
  local d = DATATYPES[dt]
  if not d or not d.m then return false end
  for _, m in ipairs(d.m) do if m == method then return true end end
  return false
end

function Api.GetSource(c)
  if CORE.libraries[c] then return 'luau-core' end
  return SOURCE[c]
end
function Api.IsInternal(c) return SOURCE[c] == 'internal' end
function Api.IsCore(c) return CORE.libraries[c] ~= nil or CORE_CAT[c] ~= nil end
function Api.IsPublic(c)
  local s = SOURCE[c]
  return s == 'public' or s == 'cdn'
end

function Api.FilterSource(source)
  local list = {}
  for cName, s in pairs(SOURCE) do
    if s == source then table.insert(list, cName) end
  end
  table.sort(list)
  return list
end

function Api.Search(pattern, limit)
  if type(pattern) ~= 'string' then return {} end
  limit = limit or 100
  local lp = '^' .. pattern:gsub('%%', '%%%%'):gsub('%.', '%.'):gsub('%*', '.*') .. '$'
  local results = {}
  for cName, d in pairs(DUMP) do
    if cName:match(lp) then
      table.insert(results, { kind = 'class', name = cName })
    end
    if d.m then
      for mn in pairs(d.m) do
        if mn:match(lp) then
          table.insert(results, { kind = 'method', name = mn, class = cName })
        end
      end
    end
    if d.e then
      for en in pairs(d.e) do
        if en:match(lp) then
          table.insert(results, { kind = 'event', name = en, class = cName })
        end
      end
    end
    if d.p then
      for pn in pairs(d.p) do
        if pn:match(lp) then
          table.insert(results, { kind = 'property', name = pn, class = cName })
        end
      end
    end
    if #results >= limit then break end
  end
  return results
end

function Api.Stats()
  local classes, methods, events, props, enums, dtypes = 0, 0, 0, 0, 0, 0
  for _ in pairs(SUPER) do classes = classes + 1 end
  for _ in pairs(ENUMS) do enums = enums + 1 end
  for _ in pairs(DATATYPES) do dtypes = dtypes + 1 end
  for _, d in pairs(DUMP) do
    if d.m then for _ in pairs(d.m) do methods = methods + 1 end end
    if d.e then for _ in pairs(d.e) do events  = events  + 1 end end
    if d.p then for _ in pairs(d.p) do props   = props   + 1 end end
  end
  return {
    classes    = classes,
    methods    = methods,
    events     = events,
    properties = props,
    enums      = enums,
    datatypes  = dtypes,
  }
end

function Api.GetClassNames()
  local names = {}
  for k in pairs(SOURCE) do table.insert(names, k) end
  table.sort(names)
  return names
end

setmetatable(Api, { __call = function(_, t, c) return Api.Get(t, c) end })

return Api